import React from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Card,
  Form,
  Input,
  Button,
  Alert,
  notification,
  Spin,
  Icon
} from 'antd'
import TokopediaEndorseWrapper from './index.style'
import TokopediaEndorseActions from '../../redux/tokopediaEndorse/actions'
import IntlMessages from '../../components/utility/intlMessages'
import { injectIntl } from 'react-intl'
import queryString from 'query-string'
import PropTypes from 'prop-types'
import Footer from '../../components/Footer/footer'

const FormItem = Form.Item
const TextArea = Input.TextArea
const {
  resetTokopediaEndorseRedux,
  getTokopediaPolicyDetails,
  postTokopediaEndorseRequest
} = TokopediaEndorseActions

class TokopediaEndorse extends React.Component {
  state = {
    internalID: null
  }
  componentWillReceiveProps (nextProps) {
    const {
      postTokopediaEndorseLoading,
      postTokopediaEndorseError,
      postTokopediaEndorseMessage
    } = nextProps
    if (!postTokopediaEndorseLoading && postTokopediaEndorseMessage) {
      notification[postTokopediaEndorseError ? 'error' : 'success']({
        message: this.intlText({ id: postTokopediaEndorseError ? 'Error' : 'disimpan' }),
        description: postTokopediaEndorseError ? this.intlText({ id: postTokopediaEndorseMessage }) : ''
      })
      this.props.resetTokopediaEndorseRedux(['postTokopediaEndorseMessage'])
    }
  }
  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }
  componentDidMount () {
    this.props.resetTokopediaEndorseRedux()
    const query = queryString.parse(window.location.search)
    this.setState({
      internalID: query.id
    })
    this.props.getTokopediaPolicyDetails({ query: { id: query.id } })
  }
  handleSubmit = async e => {
    e.preventDefault()
    const {
      internalID
    } = this.state
    const { form } = this.props
    form.validateFields(['address'], (error, values) => {
      if (!error) {
        this.props.postTokopediaEndorseRequest({ body: values, params: { id: internalID } })
      }
    })
  }
  render () {
    const { getFieldDecorator } = this.props.form
    const {
      tokopediaPolicyDetails,
      tokopediaPolicyDetailsLoading,
      tokopediaPolicyDetailsError,
      tokopediaPolicyDetailsMessage,
      postTokopediaEndorseLoading,
      postTokopediaEndorseError,
      postTokopediaEndorseData
    } = this.props
    return (
      <div>
        <TokopediaEndorseWrapper>
          <Row style={{ display: 'flex', justifyContent: 'center' }}>
            <Col xs={24} sm={24} md={12} lg={12} xl={12}>
              <Card className='form-cards'>
                <Spin
                  spinning={!!tokopediaPolicyDetailsLoading || !!postTokopediaEndorseLoading}
                  indicator={<Icon type='loading' spin />}
                >
                  {!tokopediaPolicyDetailsLoading && !!tokopediaPolicyDetailsError && (
                    <Alert
                      message='Error'
                      description={this.intlText({ id: tokopediaPolicyDetailsMessage || 'Error' })}
                      type='error'
                    />
                  )}
                  {
                    tokopediaPolicyDetails.application_no &&
                    !(!postTokopediaEndorseLoading && !postTokopediaEndorseError && !!postTokopediaEndorseData) && (
                      <Form onSubmit={this.handleSubmit} id='myForm'>
                        <h2>
                          <IntlMessages id='Aktivasi Asuransi Proteksi Furniture' />
                        </h2>
                        <p>
                          <IntlMessages id='Aktifkan Asuransi Proteksi Furniture Anda dengan mengisi alamat Rumah Tinggal (bukan apartemen, ruko, gudang, kos atau jenis bangunan lainnya) yang ingin dilindungi. Jika alamat yang dimasukkan bukan Rumah Tinggal, maka manfaat dalam Polis Anda tidak dapat di klaim.' />
                        </p>
                        <Row className='form-container'>
                          <Col
                            xs={24}
                            sm={24}
                            md={7}
                            lg={7}
                            style={{ marginTop: '8px' }}
                          >
                            <label style={{ marginTop: '10px' }}>
                              <strong>
                                <IntlMessages id='Application No' />
                              </strong>
                            </label>
                          </Col>
                          <Col xs={24} sm={24} md={17} lg={17}>
                            <FormItem>
                              {getFieldDecorator('application_no', {
                                initialValue: tokopediaPolicyDetails.application_no || '-'
                              })(<Input
                                disabled
                              />)}
                            </FormItem>
                          </Col>
                        </Row>
                        <Row className='form-container'>
                          <Col
                            xs={24}
                            sm={24}
                            md={7}
                            lg={7}
                            style={{ marginTop: '8px' }}
                          >
                            <label style={{ marginTop: '10px' }}>
                              <strong>
                                <IntlMessages id='Alamat' />
                              </strong>
                            </label>
                          </Col>
                          <Col xs={24} sm={24} md={17} lg={17}>
                            <FormItem>
                              {getFieldDecorator('address', {
                                rules: [
                                  {
                                    required: true,
                                    whitespace: true,
                                    message: (
                                      <IntlMessages id='Alamat tidak boleh kosong' />
                                    )
                                  }
                                ]
                              })(<TextArea
                                disabled={!!tokopediaPolicyDetailsError}
                                autosize={{
                                  minRows: 4,
                                  maxRows: 8
                                }}
                              />)}
                            </FormItem>
                          </Col>
                        </Row>
                        <Row>
                          <Col>
                            <div
                              className='btn-form-order-container'
                              style={{
                                display: 'flex',
                                justifyContent: 'center',
                                flexDirection: 'column',
                                alignItems: 'center'
                              }}
                            >
                              <Button
                                disabled={!tokopediaPolicyDetails.application_no || !!postTokopediaEndorseLoading}
                                type='primary'
                                className='button btn-form-order'
                                htmlType='submit'
                                form='myForm'
                                key='submit'
                              >
                                <IntlMessages id='Submit' />
                              </Button>
                            </div>
                          </Col>
                        </Row>
                      </Form>
                    )}
                  {
                    !postTokopediaEndorseLoading && !postTokopediaEndorseError && !!postTokopediaEndorseData && (
                      <div>
                        <h2><IntlMessages id='Terima kasih!' /></h2>
                        <IntlMessages id='Alamat Anda telah terdaftar dalam Asuransi Proteksi Furniture.' />
                      </div>
                    )
                  }
                </Spin>
              </Card>
            </Col>
          </Row>
        </TokopediaEndorseWrapper>
        <Footer />
      </div>

    )
  }
}

TokopediaEndorse.propTypes = {
  tokopediaPolicyDetails: PropTypes.object.isRequired
}

TokopediaEndorse.defaultProps = {
  tokopediaPolicyDetails: {}
}

const TokopediaEndorseWrapped = Form.create()(TokopediaEndorse)
export default connect(
  state => ({
    tokopediaPolicyDetails: state.TokopediaEndorse.tokopediaPolicyDetails,
    tokopediaPolicyDetailsMessage: state.TokopediaEndorse.tokopediaPolicyDetailsMessage,
    tokopediaPolicyDetailsLoading: state.Loading.GET_TOKOPEDIA_POLICY_DETAILS,
    tokopediaPolicyDetailsError: state.Error.GET_TOKOPEDIA_POLICY_DETAILS,
    postTokopediaEndorseMessage: state.TokopediaEndorse.postTokopediaEndorseMessage,
    postTokopediaEndorseData: state.TokopediaEndorse.postTokopediaEndorseData,
    postTokopediaEndorseLoading: state.Loading.POST_TOKOPEDIA_ENDORSE,
    postTokopediaEndorseError: state.Error.POST_TOKOPEDIA_ENDORSE
  }),
  {
    getTokopediaPolicyDetails,
    postTokopediaEndorseRequest,
    resetTokopediaEndorseRedux
  }
)(injectIntl(TokopediaEndorseWrapped))
